import * as React from "react";
import { Star, ThumbsUp } from "lucide-react";

export interface InteractiveRatingProps {
  /** Number of selectable scores (default 5). */
  max?: number;
  /** Initial value. */
  defaultValue?: number | null;
  /** Controlled value. */
  value?: number | null;
  /** Title shown above the scale. */
  title?: string;
  /** Subtitle / question shown beneath the title. */
  description?: string;
  /** Fired when the user selects a score. */
  onChange?: (value: number) => void;
  className?: string;
}

/**
 * InteractiveRating — accessible 1-N rating selector with a confirmation
 * line. Uses real <button> elements (keyboard + screen reader friendly).
 */
export function InteractiveRating({
  max = 5,
  defaultValue = null,
  value: controlled,
  title = "Rate component layout",
  description = "How easy was it to paste this component code?",
  onChange,
  className,
}: InteractiveRatingProps) {
  const [internal, setInternal] = React.useState<number | null>(defaultValue);
  const value = controlled !== undefined ? controlled : internal;

  const handleSelect = (next: number) => {
    if (controlled === undefined) setInternal(next);
    onChange?.(next);
  };

  return (
    <div
      role="radiogroup"
      aria-label={title}
      className={[
        "p-5 rounded-2xl border border-border bg-card text-center space-y-3 max-w-[320px]",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <h4 className="font-extrabold text-xs text-foreground uppercase tracking-wider">
        {title}
      </h4>
      <p className="text-xs text-muted-foreground">{description}</p>
      <div className="flex justify-center gap-2 pt-1">
        {Array.from({ length: max }, (_, i) => i + 1).map((score) => {
          const active = value === score;
          return (
            <button
              key={score}
              type="button"
              role="radio"
              aria-checked={active}
              aria-label={`Rate ${score} out of ${max}`}
              onClick={() => handleSelect(score)}
              className={[
                "w-8 h-8 rounded-lg text-xs font-bold transition-all border focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/60",
                active
                  ? "bg-primary border-primary text-primary-foreground scale-110"
                  : "bg-secondary/40 border-border text-muted-foreground hover:text-foreground hover:bg-secondary",
              ].join(" ")}
            >
              {score}
            </button>
          );
        })}
      </div>
      {value !== null && value !== undefined ? (
        <div
          role="status"
          className="text-[10px] text-primary font-bold flex items-center justify-center gap-1"
        >
          <ThumbsUp className="w-3 h-3" aria-hidden />
          <span>
            Thank you for your rating! ({value}/{max})
          </span>
        </div>
      ) : null}
      <Star className="sr-only" aria-hidden />
    </div>
  );
}

export default InteractiveRating;
